B.OK=new A.ey("14 Sighon ki Gardan (\u0641\u0639\u0644 \u06a9\u06cc 14 \u06af\u0631\u062f\u0627\u0646\u06cc\u06ba)","gardan","fil","\u0639\u0631\u0628\u06cc \u0645\u06cc\u06ba \u06c1\u0631 \u0641\u0639\u0644 (Verb) \u06a9\u06cc 14 \u0634\u06a9\u0644\u06cc\u06ba \u06c1\u0648\u062a\u06cc \u06c1\u06cc\u06ba: 6 \u063a\u0627\u0626\u0628\u060c 6 \u062d\u0627\u0636\u0631\u060c 2 \u0645\u062a\u06a9\u0644\u0645\u06d4","\u0639\u0631\u0628\u06cc \u0635\u0631\u0641 (Sarf) \u0645\u06cc\u06ba \u062c\u0628 \u0628\u06be\u06cc \u06a9\u0648\u0626\u06cc \u0641\u0639\u0644 \u06af\u0631\u062f\u0627\u0646\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2 \u062a\u0648 \u0641\u0627\u0639\u0644 (\u0641\u0627\u0639\u0644 \u06a9\u06d2 \u0645\u0630\u06a9\u0631/\u0645\u0624\u0646\u062b \u0627\u0648\u0631 \u0648\u0627\u062d\u062f/\u062a\u062b\u0646\u06cc\u06c1/\u062c\u0645\u0639) \u06a9\u06d2 \u0627\u0639\u062a\u0628\u0627\u0631 \u0633\u06d2 14 \u0635\u06cc\u063a\u06d2 \u0628\u0646\u062a\u06d2 \u06c1\u06cc\u06ba:\n\n1. \u0648\u0627\u062d\u062f \u0645\u0630\u06a9\u0631 \u063a\u0627\u0626\u0628 (\u0647\u064f\u0648\u064e - \u062c\u06cc\u0633\u06d2 \u062e\u064e\u0644\u064e\u0642\u064e: \u0627\u0633 \u0627\u06cc\u06a9 \u0645\u0631\u062f \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n2. \u062a\u062b\u0646\u06cc\u06c1 \u0645\u0630\u06a9\u0631 \u063a\u0627\u0626\u0628 (\u0647\u064f\u0645\u064e\u0627 - \u062e\u064e\u0644\u064e\u0642\u064e\u0627: \u0627\u0646 \u062f\u0648 \u0645\u0631\u062f\u0648\u06ba \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n3. \u062c\u0645\u0639 \u0645\u0630\u06a9\u0631 \u063a\u0627\u0626\u0628 (\u0647\u064f\u0645\u0652 - \u062e\u064e\u0644\u064e\u0642\u064f\u0648\u0627: \u0627\u0646 \u0633\u0628 \u0645\u0631\u062f\u0648\u06ba \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n4. \u0648\u0627\u062d\u062f \u0645\u0624\u0646\u062b \u063a\u0627\u0626\u0628 (\u0647\u0650\u064a\u064e - \u062e\u064e\u0644\u064e\u0642\u064e\u062a\u0652: \u0627\u0633 \u0627\u06cc\u06a9 \u0639\u0648\u0631\u062a \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n5. \u062a\u062b\u0646\u06cc\u06c1 \u0645\u0624\u0646\u062b \u063a\u0627\u0626\u0628 (\u0647\u064f\u0645\u064e\u0627 - \u062e\u064e\u0644\u064e\u0642\u064e\u062a\u064e\u0627: \u0627\u0646 \u062f\u0648 \u0639\u0648\u0631\u062a\u0648\u06ba \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n6. \u062c\u0645\u0639 \u0645\u0624\u0646\u062b \u063a\u0627\u0626\u0628 (\u0647\u064f\u0646\u0651\u064e - \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e: \u0627\u0646 \u0633\u0628 \u0639\u0648\u0631\u062a\u0648\u06ba \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n7. \u0648\u0627\u062d\u062f \u0645\u0630\u06a9\u0631 \u062d\u0627\u0636\u0631 (\u0623\u064e\u0646\u0652\u062a\u064e - \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064e: \u062a\u0648 \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n8. \u062a\u062b\u0646\u06cc\u06c1 \u0645\u0630\u06a9\u0631 \u062d\u0627\u0636\u0631 (\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u064e\u0627 - \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064f\u0645\u064e\u0627: \u062a\u0645 \u062f\u0648 \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n9. \u062c\u0645\u0639 \u0645\u0630\u06a9\u0631 \u062d\u0627\u0636\u0631 (\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 - \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064f\u0645\u0652: \u062a\u0645 \u0633\u0628 \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n10. \u0648\u0627\u062d\u062f \u0645\u0624\u0646\u062b \u062d\u0627\u0636\u0631 (\u0623\u064e\u0646\u0652\u062a\u0650 - \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u0650: \u062a\u0648 \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n11. \u062a\u062b\u0646\u06cc\u06c1 \u0645\u0624\u0646\u062b \u062d\u0627\u0636\u0631 (\u0623\u064e\u0646\u0652\u062a\u064f\u0645\u064e\u0627 - \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064f\u0645\u064e\u0627: \u062a\u0645 \u062f\u0648 \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n12. \u062c\u0645\u0639 \u0645\u0624\u0646\u062b \u062d\u0627\u0636\u0631 (\u0623\u064e\u0646\u0652\u062a\u064f\u0646\u0651\u064e - \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064f\u0646\u0651\u064e: \u062a\u0645 \u0633\u0628 \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n13. \u0648\u0627\u062d\u062f \u0645\u062a\u06a9\u0644\u0645 (\u0623\u064e\u0646\u064e\u0627 - \u062e\u064e\u0644\u064e\u0642\u0652\u062a\u064f: \u0645\u06cc\u06ba \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)\n14. \u062c\u0645\u0639 \u0645\u062a\u06a9\u0644\u0645 (\u0646\u064e\u062d\u0652\u0646\u064f - \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627: \u06c1\u0645 \u0633\u0628 \u0646\u06d2 \u0628\u0646\u0627\u06cc\u0627)",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 9: "\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646 \u0628\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0633\u064e\u062f\u0651\u064b\u0627" (\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 = \u062c\u0645\u0639 \u0645\u062a\u06a9\u0644\u0645)')
B.OL=new A.ey("Mansoob (\u0645\u0646\u0635\u0648\u0628 - Accusative Case)","irab","ism","\u0648\u06c1 \u0627\u0633\u0645 \u062c\u0633 \u067e\u0631 \u0632\u0628\u0631 (\u0641\u062a\u062d\u06c1) \u06cc\u0627 \u0627\u0633 \u06a9\u0627 \u0646\u0627\u0626\u0628 (\u0627\u0644\u0641\u060c \u06cc\u0627\u0621) \u06c1\u0648\u06d4 \u0645\u0641\u0639\u0648\u0644 \u06c1\u0645\u06cc\u0634\u06c1 \u0645\u0646\u0635\u0648\u0628 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4","\u0627\u06c1\u0645 \u0645\u0646\u0635\u0648\u0628\u0627\u062a (12 \u0627\u0642\u0633\u0627\u0645):\n1. \u0645\u0641\u0639\u0648\u0644 \u0628\u06c1 (Direct Object): \u062c\u0633 \u067e\u0631 \u06a9\u0627\u0645 \u0648\u0627\u0642\u0639 \u06c1\u0648\u060c \u062c\u06cc\u0633\u06d2: \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u0670\u0647\u064f \u0627\u0644\u0652\u0625\u0650\u0646\u0652\u0633\u064e\u0627\u0646\u064e (\u0627\u0644\u0644\u06c1 \u0646\u06d2 \u0627\u0646\u0633\u0627\u0646 \u06a9\u0648 \u067e\u06cc\u062f\u0627 \u06a9\u06cc\u0627 - \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0645\u0646\u0635\u0648\u0628 \u06c1\u06d2)\u06d4\n2. \u0645\u0641\u0639\u0648\u0644 \u0645\u0637\u0644\u0642 (Cognate Accusative): \u062a\u0627\u06a9\u06cc\u062f \u06a9\u06d2 \u0644\u06cc\u06d2 \u0641\u0639\u0644 \u06a9\u0627 \u0645\u0635\u062f\u0631 \u0622\u0646\u0627\u06d4\n3. \u0645\u0641\u0639\u0648\u0644 \u0641\u06cc\u06c1 / \u0638\u0631\u0641 (Adverb of Time/Place): \u0648\u0642\u062a \u06cc\u0627 \u062c\u06af\u06c1 \u0628\u062a\u0627\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0627\u0633\u0645\u06d4\n4. \u062d\u0627\u0644 (Circumstantial state): \u0641\u0627\u0639\u0644 \u06cc\u0627 \u0645\u0641\u0639\u0648\u0644 \u06a9\u06cc \u062d\u0627\u0644\u062a \u0628\u062a\u0627\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0644\u0641\u0638\u06d4\n5. \u0625\u0646\u0651\u064e \u06a9\u0627 \u0627\u0633\u0645: \u0625\u0646\u0651\u064e \u06a9\u06d2 \u0628\u0639\u062f \u0622\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0627\u0633\u0645 \u0645\u0646\u0635\u0648\u0628 \u06c1\u0648 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4\n\u0639\u0644\u0627\u0645\u062a\u0650 \u0646\u0635\u0628: \u0645\u0641\u0631\u062f \u0645\u06cc\u06ba \u0641\u062a\u062d\u06c1 (\u0632\u0628\u0631 \u064e \u064b)\u060c \u062a\u062b\u0646\u06cc\u06c1 \u0627\u0648\u0631 \u062c\u0645\u0639 \u0645\u06cc\u06ba \u06cc\u0627\u0621 (\u064a\u0652\u0646\u0650 / \u064a\u0652\u0646\u064e)\u06d4",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 9: "\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646 \u0628\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0633\u064e\u062f\u0651\u064b\u0627" (\u0633\u064e\u062f\u0651\u064b\u0627 \u0645\u0641\u0639\u0648\u0644 \u0628\u06c1 \u06c1\u0648\u0646\u06d2 \u06a9\u06cc \u0648\u062c\u06c1 \u0633\u06d2 \u0645\u0646\u0635\u0648\u0628 \u06c1\u06d2)')
B.OM=new A.ey("Murakkab-e-Izafi (\u0645\u0631\u06a9\u0628 \u0627\u0636\u0627\u0641\u06cc - Possessive)","murakkab","ism","\u0645\u0636\u0627\u0641 \u0627\u0648\u0631 \u0645\u0636\u0627\u0641 \u0627\u0644\u06cc\u06c1 \u06a9\u0627 \u0645\u0631\u06a9\u0628\u060c \u062c\u0633 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0627\u0633\u0645 \u06a9\u06cc \u0646\u0633\u0628\u062a \u062f\u0648\u0633\u0631\u06d2 \u0627\u0633\u0645 \u06a9\u06cc \u0637\u0631\u0641 \u06a9\u06cc \u062c\u0627\u0626\u06d2 (\u06a9\u0627\u060c \u06a9\u06cc\u060c \u06a9\u06d2)\u06d4","\u0642\u0648\u0627\u0639\u062f:\n\u2022 \u0645\u0636\u0627\u0641 (\u067e\u06c1\u0644\u0627 \u0627\u0633\u0645): \u0627\u0633 \u067e\u0631 \u0646\u06c1 \u062a\u0648 \u0627\u0644\u0641 \u0644\u0627\u0645 (\u0627\u0644\u0640) \u0622\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0646\u06c1 \u062a\u0646\u0648\u06cc\u0646\u06d4\n\u2022 \u0645\u0636\u0627\u0641 \u0627\u0644\u06cc\u06c1 (\u062f\u0648\u0633\u0631\u0627 \u0627\u0633\u0645): \u06cc\u06c1 \u06c1\u0645\u06cc\u0634\u06c1 \u0645\u062c\u0631\u0648\u0631 (Zer \u0648\u0627\u0644\u0627) \u06c1\u0648\u062a\u0627 \u06c1\u06d2!\n\u062c\u06cc\u0633\u06d2: \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u0651\u0670\u0647\u0650 (\u0627\u0644\u0644\u06c1 \u06a9\u0627 \u0631\u0633\u0648\u0644)\u060c \u0642\u064e\u0644\u0652\u0628\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 (\u0642\u0631\u0622\u0646 \u06a9\u0627 \u062f\u0644)\u06d4",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 38: "\u062a\u064e\u0642\u0652\u062f\u0650\u064a\u0631\u064f \u0671\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0671\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u0645\u0650" (\u062a\u064e\u0642\u0652\u062f\u0650\u064a\u0631\u064f \u0645\u0636\u0627\u0641 \u06c1\u06d2 \u0627\u0648\u0631 \u0671\u0644\u0652\u0639\u064e\u0632\u0650\u064a\u0632\u0650 \u0645\u0636\u0627\u0641 \u0627\u0644\u06cc\u06c1 \u0645\u062c\u0631\u0648\u0631 \u06c1\u06d2)')
B.ON=new A.ey("Murakkab-e-Tauseefi (\u0645\u0631\u06a9\u0628 \u062a\u0648\u0635\u06cc\u0641\u06cc - Descriptive)","murakkab","ism","\u0645\u0648\u0635\u0648\u0641 \u0627\u0648\u0631 \u0635\u0641\u062a \u06a9\u0627 \u0645\u062c\u0645\u0648\u0639\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u062f\u0648\u0633\u0631\u0627 \u0627\u0633\u0645 \u067e\u06c1\u0644\u06d2 \u0627\u0633\u0645 \u06a9\u06cc \u0627\u0686\u06be\u0627\u0626\u06cc \u06cc\u0627 \u0628\u0631\u0627\u0626\u06cc \u0628\u06cc\u0627\u0646 \u06a9\u0631\u06d2\u06d4","\u0642\u0627\u0639\u062f\u06c1: \u0635\u0641\u062a \u0627\u067e\u0646\u06d2 \u0645\u0648\u0635\u0648\u0641 \u06a9\u06d2 4 \u0627\u0645\u0648\u0631 \u0645\u06cc\u06ba 100% \u062a\u0627\u0628\u0639 \u06c1\u0648\u062a\u06cc \u06c1\u06d2:\n1. \u0627\u0639\u0631\u0627\u0628 \u0645\u06cc\u06ba (\u062f\u0648\u0646\u0648\u06ba \u0645\u0631\u0641\u0648\u0639\u060c \u06cc\u0627 \u062f\u0648\u0646\u0648\u06ba \u0645\u0646\u0635\u0648\u0628\u060c \u06cc\u0627 \u062f\u0648\u0646\u0648\u06ba \u0645\u062c\u0631\u0648\u0631)\n2. \u062c\u0646\u0633 \u0645\u06cc\u06ba (\u062f\u0648\u0646\u0648\u06ba \u0645\u0630\u06a9\u0631 \u06cc\u0627 \u062f\u0648\u0646\u0648\u06ba \u0645\u0624\u0646\u062b)\n3. \u0639\u062f\u062f \u0645\u06cc\u06ba (\u062f\u0648\u0646\u0648\u06ba \u0648\u0627\u062d\u062f\u060c \u062a\u062b\u0646\u06cc\u06c1 \u06cc\u0627 \u062c\u0645\u0639)\n4. \u0648\u0633\u0639\u062a \u0645\u06cc\u06ba (\u062f\u0648\u0646\u0648\u06ba \u0645\u0639\u0631\u0641\u06c1 \u06cc\u0627 \u062f\u0648\u0646\u0648\u06ba \u0646\u06a9\u0631\u06c1)",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 4: "\u0635\u0650\u0631\u064e\u0670\u0637\u064d \u0645\u064f\u0651\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d" (\u0635\u0650\u0631\u064e\u0627\u0637\u064d \u0645\u0648\u0635\u0648\u0641 \u06c1\u06d2 \u0627\u0648\u0631 \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d \u0627\u0633 \u06a9\u06cc \u0635\u0641\u062a \u06c1\u06d2)')
B.OO=new A.ey("Marfu\u2019 (\u0645\u0631\u0641\u0648\u0639 - Nominative Case)","irab","ism","\u0648\u06c1 \u0627\u0633\u0645 \u062c\u0633 \u067e\u0631 \u067e\u06cc\u0634 (\u0636\u0645\u06c1) \u06cc\u0627 \u0627\u0633 \u06a9\u0627 \u0646\u0627\u0626\u0628 (\u0648\u0627\u0624\u060c \u0627\u0644\u0641) \u06c1\u0648\u06d4","\u0627\u06c1\u0645 \u0645\u0631\u0641\u0648\u0639\u0627\u062a:\n1. \u0627\u0644\u0641\u0627\u0639\u0644 (Fa\u2019il - \u06a9\u0627\u0645 \u06a9\u0631\u0646\u06d2 \u0648\u0627\u0644\u0627): \u062c\u06cc\u0633\u06d2 \u062c\u064e\u0627\u0621\u064e \u0631\u064e\u062c\u064f\u0644\u064c (\u0622\u062f\u0645\u06cc \u0622\u06cc\u0627)\u06d4 \u0641\u0627\u0639\u0644 \u06c1\u0645\u06cc\u0634\u06c1 \u0645\u0631\u0641\u0648\u0639 \u06c1\u0648\u062a\u0627 \u06c1\u06d2!\n2. \u0646\u0627\u0626\u0628 \u0627\u0644\u0641\u0627\u0639\u0644 (Passive Subject): \u0641\u0639\u0644 \u0645\u062c\u06c1\u0648\u0644 \u06a9\u06d2 \u0628\u0639\u062f \u0622\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0627\u0633\u0645\u06d4\n3. \u0627\u0644\u0645\u0628\u062a\u062f\u0623 (Mubtada): \u062c\u0645\u0644\u06c1 \u0627\u0633\u0645\u06cc\u06c1 \u06a9\u0627 \u067e\u06c1\u0644\u0627 \u062d\u0635\u06c1\u06d4\n4. \u0627\u0644\u062e\u0628\u0631 (Khabar): \u062c\u0645\u0644\u06c1 \u0627\u0633\u0645\u06cc\u06c1 \u06a9\u0627 \u062f\u0648\u0633\u0631\u0627 \u062d\u0635\u06c1 \u062c\u0648 \u0645\u0628\u062a\u062f\u0627 \u06a9\u06cc \u062e\u0628\u0631 \u062f\u06cc\u062a\u0627 \u06c1\u06d2\u06d4\n\u0639\u0644\u0627\u0645\u062a\u0650 \u0631\u0641\u0639: \u0645\u0641\u0631\u062f \u0645\u06cc\u06ba \u0636\u0645\u06c1 (\u067e\u06cc\u0634 \u064f \u064c)\u060c \u062a\u062b\u0646\u06cc\u06c1 \u0645\u06cc\u06ba \u0627\u0644\u0641 (\u0627\u0646\u0650)\u060c \u0627\u0648\u0631 \u062c\u0645\u0639 \u0645\u0630\u06a9\u0631 \u0633\u0627\u0644\u0645 \u0645\u06cc\u06ba \u0648\u0627\u0624 (\u0648\u0646\u064e)\u06d4",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 20: "\u0648\u064e\u062c\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u0623\u064e\u0642\u0652\u0635\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u0631\u064e\u062c\u064f\u0644\u064c" (\u0631\u064e\u062c\u064f\u0644\u064c \u0645\u0631\u0641\u0648\u0639 \u06c1\u06d2 \u06a9\u06cc\u0648\u0646\u06a9\u06c1 \u06cc\u06c1 \u0641\u0627\u0639\u0644 \u06c1\u06d2)')
B.OP=new A.ey("Harf (\u062d\u0631\u0641 - Particle)","buniyadi","harf","\u0627\u06cc\u0633\u0627 \u0644\u0641\u0638 \u062c\u0648 \u0627\u06a9\u06cc\u0644\u0627 \u0627\u067e\u0646\u0627 \u067e\u0648\u0631\u0627 \u0645\u0641\u06c1\u0648\u0645 \u0638\u0627\u06c1\u0631 \u0646\u06c1 \u06a9\u0631 \u0633\u06a9\u06d2 \u0628\u0644\u06a9\u06c1 \u0627\u0633\u0645 \u06cc\u0627 \u0641\u0639\u0644 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0645\u0644 \u06a9\u0631 \u0645\u0639\u0646\u06cc \u062f\u06d2\u06d4","\u062d\u0631\u0641 \u06a9\u0627 \u0627\u067e\u0646\u0627 \u06a9\u0648\u0626\u06cc \u0622\u0632\u0627\u062f\u0627\u0646\u06c1 \u0632\u0645\u0627\u0646\u06c1 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u0627\u06d4 \u06cc\u06c1 \u062c\u0645\u0644\u06d2 \u06a9\u06d2 \u0627\u062c\u0632\u0627\u0621 \u06a9\u0648 \u0622\u067e\u0633 \u0645\u06cc\u06ba \u062c\u0648\u0691\u062a\u0627 \u06c1\u06d2\u06d4\n\u0639\u0631\u0628\u06cc \u0645\u06cc\u06ba \u062d\u0631\u0648\u0641 \u06a9\u06cc \u0645\u062a\u0639\u062f\u062f \u0627\u0642\u0633\u0627\u0645 \u06c1\u06cc\u06ba \u062c\u06cc\u0633\u06d2 \u062d\u0631\u0648\u0641\u0650 \u062c\u0627\u0631\u06c1 (\u0645\u0650\u0646\u0652\u060c \u0625\u0650\u0644\u064e\u0649)\u060c \u062d\u0631\u0648\u0641\u0650 \u0639\u0627\u0637\u0641\u06c1 (\u0648\u064e\u060c \u0641\u064e)\u060c \u062d\u0631\u0648\u0641\u0650 \u0646\u062f\u0627\u0621 (\u064a\u064e\u0627)\u060c \u062d\u0631\u0648\u0641\u0650 \u0646\u0641\u06cc (\u0644\u064e\u0627\u060c \u0645\u064e\u0627)\u060c \u0627\u0648\u0631 \u062d\u0631\u0648\u0641\u0650 \u0645\u0634\u0628\u06c1 \u0628\u0627\u0644\u0641\u0639\u0644 (\u0625\u0650\u0646\u0651\u064e\u060c \u0623\u064e\u0646\u0651\u064e)\u06d4 \u062a\u0645\u0627\u0645 \u062d\u0631\u0648\u0641 \u0645\u0628\u0646\u06cc (Mabni) \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 4: "\u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u064d \u0645\u064f\u0651\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d" (\u0639\u064e\u0644\u064e\u0649 = \u062d\u0631\u0641\u0650 \u062c\u0631)')
B.OQ=new A.ey("Majroor (\u0645\u062c\u0631\u0648\u0631 - Genitive Case)","irab","ism","\u0648\u06c1 \u0627\u0633\u0645 \u062c\u0633 \u06a9\u06d2 \u0646\u06cc\u0686\u06d2 \u0632\u06cc\u0631 (\u06a9\u0633\u0631\u06c1) \u06cc\u0627 \u0627\u0633 \u06a9\u0627 \u0646\u0627\u0626\u0628 (\u06cc\u0627\u0621) \u06c1\u0648\u06d4","\u0627\u0633\u0645 \u0635\u0631\u0641 \u062f\u0648 \u062d\u0627\u0644\u062a\u0648\u06ba \u0645\u06cc\u06ba \u0645\u062c\u0631\u0648\u0631 \u06c1\u0648\u062a\u0627 \u06c1\u06d2:\n\n1. \u062c\u0628 \u0627\u0633 \u0633\u06d2 \u067e\u06c1\u0644\u06d2 \u06a9\u0648\u0626\u06cc \u062d\u0631\u0641\u0650 \u062c\u0631 \u0622\u0626\u06d2 (\u0645\u062c\u0631\u0648\u0631 \u0628\u062d\u0631\u0641\u0650 \u062c\u0631):\n\u062c\u06cc\u0633\u06d2: \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u064d\u060c \u0639\u064e\u0644\u064e\u0649 \u0635\u0650\u0631\u064e\u0627\u0637\u064d\u060c \u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u0670\u0647\u0650\n\n2. \u062c\u0628 \u0648\u06c1 \u0645\u0636\u0627\u0641 \u0627\u0644\u06cc\u06c1 (Mudaf Ilayh) \u0628\u0646\u06d2 (\u0645\u062c\u0631\u0648\u0631 \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629):\n\u062c\u06cc\u0633\u06d2: \u0642\u064e\u0644\u0652\u0628\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 (\u0642\u0631\u0622\u0646 \u06a9\u0627 \u062f\u0644 - \u0627\u0644\u0642\u0631\u0622\u0646\u0650 \u0645\u062c\u0631\u0648\u0631 \u06c1\u06d2 \u06a9\u06cc\u0648\u0646\u06a9\u06c1 \u0645\u0636\u0627\u0641 \u0627\u0644\u06cc\u06c1 \u06c1\u06d2)\u06d4\n\n\u0639\u0644\u0627\u0645\u062a\u0650 \u062c\u0631: \u0645\u0641\u0631\u062f \u0645\u06cc\u06ba \u06a9\u0633\u0631\u06c1 (\u0632\u06cc\u0631 \u0650 \u064d)\u060c \u062a\u062b\u0646\u06cc\u06c1 \u0648 \u062c\u0645\u0639 \u0645\u0630\u06a9\u0631 \u0633\u0627\u0644\u0645 \u0645\u06cc\u06ba \u06cc\u0627\u0621 \u0645\u0627\u0642\u0628\u0644 \u0645\u0641\u062a\u0648\u062d/\u0645\u06a9\u0633\u0648\u0631\u06d4",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 4: "\u0639\u064e\u0644\u064e\u0649\u0670 \u0635\u0650\u0631\u064e\u0670\u0637\u064d \u0645\u064f\u0651\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d" (\u0635\u0650\u0631\u064e\u0627\u0637\u064d \u062d\u0631\u0641\u0650 \u062c\u0631 "\u0639\u064e\u0644\u064e\u0649" \u06a9\u06cc \u0648\u062c\u06c1 \u0633\u06d2 \u0645\u062c\u0631\u0648\u0631 \u06c1\u06d2)')
B.OR=new A.ey("Zameer Muttasil (\u0636\u0645\u06cc\u0631 \u0645\u062a\u0635\u0644 - Attached Pronoun)","zameer","zameer","\u0648\u06c1 \u0636\u0645\u06cc\u0631 \u062c\u0648 \u06a9\u0633\u06cc \u0627\u0633\u0645\u060c \u0641\u0639\u0644 \u06cc\u0627 \u062d\u0631\u0641 \u06a9\u06d2 \u0622\u062e\u0631 \u0645\u06cc\u06ba \u062c\u0691 \u06a9\u0631 \u0622\u0626\u06d2\u06d4","\u062c\u06cc\u0633\u06d2: \u0643\u064e (\u062a\u06cc\u0631\u0627/\u062a\u062c\u06be \u06a9\u0648)\u060c \u0647\u064f (\u0627\u0633 \u06a9\u0627/\u0627\u0633 \u06a9\u0648)\u060c \u0647\u064e\u0627 (\u0627\u0633 \u0639\u0648\u0631\u062a \u06a9\u0627)\u060c \u0646\u064e\u0627 (\u06c1\u0645\u0627\u0631\u0627/\u06c1\u0645 \u06a9\u0648)\u060c \u064a (\u0645\u06cc\u0631\u0627/\u0645\u062c\u06be \u06a9\u0648)\u06d4\n\n\u2022 \u0627\u06af\u0631 \u0627\u0633\u0645 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u062c\u0691\u06d2 \u062a\u0648 \u0645\u0636\u0627\u0641 \u0627\u0644\u06cc\u06c1 \u0628\u0646\u062a\u06cc \u06c1\u06d2 (\u062c\u06cc\u0633\u06d2: \u0643\u0650\u062a\u064e\u0627\u0628\u064f\u0643\u064e = \u062a\u06cc\u0631\u06cc \u06a9\u062a\u0627\u0628)\u06d4\n\u2022 \u0627\u06af\u0631 \u0641\u0639\u0644 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u062c\u0691\u06d2 \u062a\u0648 \u0645\u0641\u0639\u0648\u0644 \u0628\u06c1 \u0628\u0646\u062a\u06cc \u06c1\u06d2 (\u062c\u06cc\u0633\u06d2: \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f = \u06c1\u0645 \u0646\u06d2 \u0627\u0633\u06d2 \u0628\u0646\u0627\u06cc\u0627)\u06d4\n\u2022 \u0627\u06af\u0631 \u062d\u0631\u0641\u0650 \u062c\u0631 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u062c\u0691\u06d2 \u062a\u0648 \u0645\u062c\u0631\u0648\u0631 \u0628\u0646\u062a\u06cc \u06c1\u06d2 (\u062c\u06cc\u0633\u06d2: \u0644\u064e\u0643\u064e = \u062a\u06cc\u0631\u06d2 \u0644\u06cc\u06d2\u060c \u0641\u0650\u064a\u0647\u0650 = \u0627\u0633 \u0645\u06cc\u06ba)\u06d4",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 3: "\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e" (\u0643\u064e = \u0636\u0645\u06cc\u0631 \u0645\u062a\u0635\u0644 \u062d\u0627\u0636\u0631)')
B.OS=new A.ey("Zameer Munfasil (\u0636\u0645\u06cc\u0631 \u0645\u0646\u0641\u0635\u0644 - Detached Pronoun)","zameer","zameer","\u0648\u06c1 \u0636\u0645\u06cc\u0631 \u062c\u0648 \u0627\u06a9\u06cc\u0644\u06cc \u0627\u0644\u06af \u0644\u0641\u0638 \u06a9\u06d2 \u0637\u0648\u0631 \u067e\u0631 \u0644\u06a9\u06be\u06cc \u0627\u0648\u0631 \u067e\u0691\u06be\u06cc \u062c\u0627\u0626\u06d2 (\u06a9\u0644 14 \u0636\u0645\u0627\u0626\u0631)\u06d4","\u0636\u0645\u0627\u0626\u0631 \u0645\u0646\u0641\u0635\u0644\u06c1 \u0645\u0631\u0641\u0648\u0639\u06c1 (14 \u0627\u0644\u0641\u0627\u0638):\n\u2022 \u063a\u0627\u0626\u0628 \u0645\u0630\u06a9\u0631: \u0647\u064f\u0648\u064e (\u0648\u06c1 \u0627\u06cc\u06a9)\u060c \u0647\u064f\u0645\u064e\u0627 (\u0648\u06c1 \u062f\u0648)\u060c \u0647\u064f\u0645\u0652 (\u0648\u06c1 \u0633\u0628)\n\u2022 \u063a\u0627\u0626\u0628 \u0645\u0624\u0646\u062b: \u0647\u0650\u064a\u064e (\u0648\u06c1 \u0627\u06cc\u06a9 \u0639\u0648\u0631\u062a)\u060c \u0647\u064f\u0645\u064e\u0627 (\u0648\u06c1 \u062f\u0648 \u0639\u0648\u0631\u062a\u06cc\u06ba)\u060c \u0647\u064f\u0646\u0651\u064e (\u0648\u06c1 \u0633\u0628 \u0639\u0648\u0631\u062a\u06cc\u06ba)\n\u2022 \u062d\u0627\u0636\u0631 \u0645\u0630\u06a9\u0631: \u0623\u064e\u0646\u0652\u062a\u064e (\u062a\u0648 \u0627\u06cc\u06a9 \u0645\u0631\u062f)\u060c \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u064e\u0627 (\u062a\u0645 \u062f\u0648 \u0645\u0631\u062f)\u060c \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u0652 (\u062a\u0645 \u0633\u0628 \u0645\u0631\u062f)\n\u2022 \u062d\u0627\u0636\u0631 \u0645\u0624\u0646\u062b: \u0623\u064e\u0646\u0652\u062a\u0650 (\u062a\u0648 \u0627\u06cc\u06a9 \u0639\u0648\u0631\u062a)\u060c \u0623\u064e\u0646\u0652\u062a\u064f\u0645\u064e\u0627 (\u062a\u0645 \u062f\u0648 \u0639\u0648\u0631\u062a\u06cc\u06ba)\u060c \u0623\u064e\u0646\u0652\u062a\u064f\u0646\u0651\u064e (\u062a\u0645 \u0633\u0628 \u0639\u0648\u0631\u062a\u06cc\u06ba)\n\u2022 \u0645\u062a\u06a9\u0644\u0645: \u0623\u064e\u0646\u064e\u0627 (\u0645\u06cc\u06ba)\u060c \u0646\u064e\u062d\u0652\u0646\u064f (\u06c1\u0645 \u0633\u0628)",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 69: "\u0625\u0650\u0646\u0652 \u0647\u064f\u0648\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0630\u0650\u0643\u0652\u0631\u064c \u0648\u064e\u0642\u064f\u0631\u0652\u0622\u0646\u064c \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c" (\u0647\u064f\u0648\u064e = \u0636\u0645\u06cc\u0631 \u0645\u0646\u0641\u0635\u0644 \u0648\u0627\u062d\u062f \u0645\u0630\u06a9\u0631 \u063a\u0627\u0626\u0628)')
B.OT=new A.ey("Ism (\u0627\u0633\u0645 - Noun/Adjective)","buniyadi","ism","\u06a9\u0633\u06cc \u0634\u062e\u0635\u060c \u062c\u06af\u06c1\u060c \u0686\u06cc\u0632\u060c \u06a9\u0627\u0645 \u06cc\u0627 \u0635\u0641\u062a \u06a9\u0627 \u0646\u0627\u0645 \u062c\u0648 \u0632\u0645\u0627\u0646\u06d2 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u0645\u06a9\u0645\u0644 \u0645\u0639\u0646\u06cc \u062f\u06d2\u06d4","\u0627\u0633\u0645 \u06a9\u06cc \u0646\u0634\u0627\u0646\u06cc\u0627\u06ba:\n\u2022 \u0634\u0631\u0648\u0639 \u0645\u06cc\u06ba \u0627\u0644\u0641 \u0644\u0627\u0645 (\u0627\u0644\u0640) \u0622\u0646\u0627\u060c \u062c\u06cc\u0633\u06d2: \u0627\u064e\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f\u060c \u0627\u064e\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u064f\n\u2022 \u0622\u062e\u0631 \u067e\u0631 \u062a\u0646\u0648\u06cc\u0646 (\u064b \u064d \u064c) \u0622\u0646\u0627\u060c \u062c\u06cc\u0633\u06d2: \u0635\u0650\u0631\u064e\u0627\u0637\u064d\u060c \u0645\u064f\u0633\u0652\u062a\u064e\u0642\u0650\u064a\u0645\u064d\n\u2022 \u0627\u0633 \u0633\u06d2 \u067e\u06c1\u0644\u06d2 \u062d\u0631\u0641\u0650 \u062c\u0631 \u0622\u0646\u0627\u060c \u062c\u06cc\u0633\u06d2: \u0639\u064e\u0644\u064e\u0649 \u0635\u0650\u0631\u064e\u0627\u0637\u064d\n\u2022 \u06af\u0648\u0644 \u062a\u0627\u0621 (\u0629) \u06a9\u0627 \u06c1\u0648\u0646\u0627\u060c \u062c\u06cc\u0633\u06d2: \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064c\u060c \u0622\u064a\u064e\u0629\u064c\n\n\u0627\u0633\u0645 \u06a9\u06cc \u0627\u0639\u0631\u0627\u0628\u06cc \u062d\u0627\u0644\u062a\u06cc\u06ba 3 \u06c1\u0648\u062a\u06cc \u06c1\u06cc\u06ba: \u0645\u0631\u0641\u0648\u0639 (Pesh)\u060c \u0645\u0646\u0635\u0648\u0628 (Zabar)\u060c \u0645\u062c\u0631\u0648\u0631 (Zer)\u06d4",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 2: "\u0648\u064e\u0671\u0644\u0652\u0642\u064f\u0631\u0652\u0621\u064e\u0627\u0646\u0650 \u0671\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u0650" (\u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0648\u0631 \u0627\u0644\u062d\u06a9\u06cc\u0645 \u062f\u0648\u0646\u0648\u06ba \u0627\u0633\u0645 \u06c1\u06cc\u06ba)')
B.OU=new A.ey("Fe\u2019l (\u0641\u0639\u0644 - Verb)","buniyadi","fil","\u0627\u06cc\u0633\u0627 \u06a9\u0644\u0645\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u06a9\u0633\u06cc \u06a9\u0627\u0645 \u06a9\u0627 \u06a9\u0631\u0646\u0627 \u06cc\u0627 \u06c1\u0648\u0646\u0627 \u06a9\u0633\u06cc \u0632\u0645\u0627\u0646\u06d2 (\u0645\u0627\u0636\u06cc\u060c \u062d\u0627\u0644\u060c \u0645\u0633\u062a\u0642\u0628\u0644) \u06a9\u06d2 \u0633\u0627\u062a\u06be \u067e\u0627\u06cc\u0627 \u062c\u0627\u0626\u06d2\u06d4","\u0641\u0639\u0644 \u06a9\u06cc \u0628\u0646\u06cc\u0627\u062f\u06cc \u0627\u0642\u0633\u0627\u0645:\n1. \u0641\u0639\u0644 \u0645\u0627\u0636\u06cc (Past Tense): \u062c\u0648 \u06a9\u0627\u0645 \u06af\u0632\u0631\u06d2 \u06c1\u0648\u0626\u06d2 \u0632\u0645\u0627\u0646\u06d2 \u0645\u06cc\u06ba \u06c1\u0648\u0627\u060c \u062c\u06cc\u0633\u06d2: \u062e\u064e\u0644\u064e\u0642\u064e (\u0627\u0633 \u0646\u06d2 \u067e\u06cc\u062f\u0627 \u06a9\u06cc\u0627)\u060c \u0642\u064e\u0627\u0644\u064e (\u0627\u0633 \u0646\u06d2 \u06a9\u06c1\u0627)\u06d4\n2. \u0641\u0639\u0644 \u0645\u0636\u0627\u0631\u0639 (Present/Future): \u062c\u0648 \u06a9\u0627\u0645 \u0645\u0648\u062c\u0648\u062f\u06c1 \u06cc\u0627 \u0622\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0632\u0645\u0627\u0646\u06d2 \u0645\u06cc\u06ba \u06c1\u0648\u060c \u062c\u06cc\u0633\u06d2: \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f (\u0648\u06c1 \u067e\u06cc\u062f\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u06cc\u0627 \u06a9\u0631\u06d2 \u06af\u0627)\u060c \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e (\u0648\u06c1 \u062c\u0627\u0646\u062a\u06d2 \u06c1\u06cc\u06ba)\u06d4\n3. \u0641\u0639\u0644 \u0627\u0645\u0631 (Imperative): \u06a9\u0633\u06cc \u06a9\u0627\u0645 \u06a9\u0627 \u062d\u06a9\u0645 \u062f\u06cc\u0646\u0627\u060c \u062c\u06cc\u0633\u06d2: \u0642\u064f\u0644\u0652 (\u06a9\u06c1\u06c1 \u062f\u06cc\u062c\u06cc\u06d2!)\u060c \u0627\u0650\u0639\u0652\u0644\u064e\u0645\u0652 (\u062c\u0627\u0646 \u0644\u0648!)\u06d4\n4. \u0641\u0639\u0644 \u0646\u06c1\u06cc (Prohibition): \u06a9\u0633\u06cc \u06a9\u0627\u0645 \u0633\u06d2 \u0631\u0648\u06a9\u0646\u0627\u060c \u062c\u06cc\u0633\u06d2: \u0644\u064e\u0627 \u062a\u064e\u0641\u0652\u0639\u064e\u0644\u0652 (\u0645\u062a \u06a9\u0631!)\u06d4",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 77: "\u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0631\u064e \u0671\u0644\u0652\u0625\u0650\u0646\u0633\u064e\u0670\u0646\u064f \u0623\u064e\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0670\u0647\u064f" (\u062e\u064e\u0644\u064e\u0642\u0652\u0646\u064e\u0627 = \u0641\u0639\u0644 \u0645\u0627\u0636\u06cc)')
B.OV=new A.ey("Huroof-e-Mushabbah bil-Fe\u2019l (\u062d\u0631\u0648\u0641\u0650 \u0645\u0634\u0628\u06c1 \u0628\u0627\u0644\u0641\u0639\u0644)","huroof","harf","\u0648\u06c1 6 \u062d\u0631\u0648\u0641 \u062c\u0648 \u062c\u0645\u0644\u06c1 \u0627\u0633\u0645\u06cc\u06c1 \u067e\u0631 \u062f\u0627\u062e\u0644 \u06c1\u0648 \u06a9\u0631 \u0645\u0628\u062a\u062f\u0627 \u06a9\u0648 \u0632\u0628\u0631 (\u0646\u0635\u0628) \u0627\u0648\u0631 \u062e\u0628\u0631 \u06a9\u0648 \u067e\u06cc\u0634 (\u0631\u0641\u0639) \u062f\u06cc\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u06cc\u06c1 6 \u062d\u0631\u0648\u0641 \u06c1\u06cc\u06ba:\n1. \u0625\u0650\u0646\u0651\u064e (\u0628\u06cc\u0634\u06a9 - \u062a\u0627\u06a9\u06cc\u062f \u06a9\u06d2 \u0644\u06cc\u06d2)\n2. \u0623\u064e\u0646\u0651\u064e (\u06a9\u06c1 - \u0648\u0636\u0627\u062d\u062a \u06a9\u06d2 \u0644\u06cc\u06d2)\n3. \u0643\u064e\u0623\u064e\u0646\u0651\u064e (\u06af\u0648\u06cc\u0627 \u06a9\u06c1 - \u062a\u0634\u0628\u06cc\u06c1 \u06a9\u06d2 \u0644\u06cc\u06d2)\n4. \u0644\u064e\u0643\u0650\u0646\u0651\u064e (\u0644\u06cc\u06a9\u0646 - \u0627\u0633\u062a\u062f\u0631\u0627\u06a9 \u06a9\u06d2 \u0644\u06cc\u06d2)\n5. \u0644\u064e\u064a\u0652\u062a\u064e (\u06a9\u0627\u0634 - \u062a\u0645\u0646\u0627 \u06a9\u06d2 \u0644\u06cc\u06d2)\n6. \u0644\u064e\u0639\u064e\u0644\u0651\u064e (\u0634\u0627\u06cc\u062f / \u062a\u0627\u06a9\u06c1 - \u0627\u0645\u06cc\u062f \u06a9\u06d2 \u0644\u06cc\u06d2)",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 3: "\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0645\u0650\u0646\u064e \u0671\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e" (\u0625\u0650\u0646\u0651\u064e \u062d\u0631\u0641\u0650 \u0645\u0634\u0628\u06c1 \u0628\u0627\u0644\u0641\u0639\u0644 \u06c1\u06d2\u060c \u0643\u064e \u0627\u0633 \u06a9\u0627 \u0627\u0633\u0645 \u06c1\u06d2)')
B.OW=new A.ey("Huroof-e-Jarah (\u062d\u0631\u0648\u0641\u0650 \u062c\u0627\u0631\u06c1 - Prepositions)","huroof","harf","\u0648\u06c1 \u062d\u0631\u0648\u0641 \u062c\u0648 \u0627\u067e\u0646\u06d2 \u0628\u0639\u062f \u0622\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0627\u0633\u0645 \u06a9\u0648 \u0632\u06cc\u0631 (\u06a9\u0633\u0631\u06c1 / \u062d\u0627\u0644\u062a\u0650 \u062c\u0631) \u062f\u06cc\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u0645\u0634\u0647\u0648\u0631 17 \u062d\u0631\u0648\u0641\u0650 \u062c\u0627\u0631\u06c1 \u06a9\u0627 \u0634\u0639\u0631:\n\u0628\u0627\u060c \u062a\u0627\u060c \u06a9\u0627\u0641\u060c \u0644\u0627\u0645\u060c \u0648\u0627\u0624\u060c \u0645\u0646\u0630\u060c \u0645\u0630\u060c \u062e\u0644\u0627\n\u0631\u0628\u060c \u062d\u0627\u0634\u0627\u060c \u0645\u0646\u060c \u0639\u062f\u0627\u060c \u0641\u06cc\u060c \u0639\u0646\u060c \u0639\u0644\u06cc\u060c \u062d\u062a\u06cc\u060c \u0627\u0644\u06cc\n\n\u0642\u0631\u0622\u0646 \u0645\u06cc\u06ba \u06a9\u062b\u0631\u062a \u0633\u06d2 \u0645\u0633\u062a\u0639\u0645\u0644:\n\u2022 \u0645\u0650\u0646\u0652 (\u0633\u06d2): \u0645\u0650\u0646\u0652 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u0670\u0647\u0650\n\u2022 \u0625\u0650\u0644\u064e\u0649 (\u06a9\u06cc \u0637\u0631\u0641): \u0625\u0650\u0644\u064e\u0649 \u0635\u0650\u0631\u064e\u0627\u0637\u064d\n\u2022 \u0641\u0650\u064a (\u0645\u06cc\u06ba): \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d\n\u2022 \u0639\u064e\u0644\u064e\u0649 (\u067e\u0631): \u0639\u064e\u0644\u064e\u0649 \u0635\u0650\u0631\u064e\u0627\u0637\u064d\n\u2022 \u0628\u0650\u0640 (\u0633\u0627\u062a\u06be/\u0633\u06d2): \u0628\u0650\u0625\u0650\u0645\u064e\u0627\u0645\u064d \u0645\u064f\u0628\u0650\u064a\u0646\u064d\n\u2022 \u0644\u0650\u0640 (\u06a9\u06d2 \u0644\u06cc\u06d2): \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e\n\u2022 \u0648\u064e (\u0642\u0633\u0645\u06cc\u06c1): \u0648\u064e\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0627\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u0650",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 2: "\u0648\u064e\u0671\u0644\u0652\u0642\u064f\u0631\u0652\u0621\u064e\u0627\u0646\u0650 \u0671\u0644\u0652\u062d\u064e\u0643\u0650\u064a\u0645\u0650" (\u0648\u0627\u0624 \u0642\u0633\u0645\u06cc\u06c1 \u062d\u0631\u0641\u0650 \u062c\u0631 \u06c1\u06d2\u060c \u0627\u0633 \u0644\u06cc\u06d2 \u0627\u0644\u0642\u0631\u0622\u0646\u0650 \u0645\u062c\u0631\u0648\u0631 \u06c1\u06d2)')
B.OX=new A.ey("Mabni aur Mu\u2019rab (\u0645\u0628\u0646\u06cc \u0627\u0648\u0631 \u0645\u0639\u0631\u0628)","irab","ism","\u0645\u0628\u0646\u06cc \u0648\u06c1 \u06c1\u06d2 \u062c\u0633 \u06a9\u0627 \u0622\u062e\u0631\u06cc \u0627\u0639\u0631\u0627\u0628 \u06a9\u0628\u06be\u06cc \u0646\u06c1 \u0628\u062f\u0644\u06d2\u060c \u0627\u0648\u0631 \u0645\u0639\u0631\u0628 \u0648\u06c1 \u06c1\u06d2 \u062c\u0633 \u06a9\u0627 \u0627\u0639\u0631\u0627\u0628 \u0639\u0627\u0645\u0644 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0628\u062f\u0644\u06d2\u06d4","\u2022 \u0645\u0628\u0646\u06cc (Mabni): \u0648\u06c1 \u06a9\u0644\u0645\u0627\u062a \u062c\u0646 \u067e\u0631 \u0639\u0648\u0627\u0645\u0644 \u06a9\u0627 \u0627\u062b\u0631 \u06c1\u0648\u0646\u06d2 \u06a9\u06d2 \u0628\u0627\u0648\u062c\u0648\u062f \u0627\u0646 \u06a9\u06cc \u0638\u0627\u06c1\u0631\u06cc \u0634\u06a9\u0644 \u0646\u06c1\u06cc\u06ba \u0628\u062f\u0644\u062a\u06cc\u06d4 \u062a\u0645\u0627\u0645 \u062d\u0631\u0648\u0641\u060c \u0641\u0639\u0644 \u0645\u0627\u0636\u06cc\u060c \u0641\u0639\u0644 \u0627\u0645\u0631\u060c \u0636\u0645\u0627\u0626\u0631 \u0627\u0648\u0631 \u0627\u0633\u0645\u0627\u0626\u06d2 \u0627\u0634\u0627\u0631\u06c1 \u0645\u0628\u0646\u06cc \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4\n\u2022 \u0645\u0639\u0631\u0628 (Mu\u2019rab): \u0648\u06c1 \u06a9\u0644\u0645\u0627\u062a \u062c\u0646 \u06a9\u06cc \u0622\u062e\u0631\u06cc \u062d\u0631\u06a9\u062a \u062d\u0627\u0644\u062a\u0650 \u0631\u0641\u0639 \u0645\u06cc\u06ba \u067e\u06cc\u0634\u060c \u062d\u0627\u0644\u062a\u0650 \u0646\u0635\u0628 \u0645\u06cc\u06ba \u0632\u0628\u0631 \u0627\u0648\u0631 \u062d\u0627\u0644\u062a\u0650 \u062c\u0631 \u0645\u06cc\u06ba \u0632\u06cc\u0631 \u0645\u06cc\u06ba \u062a\u0628\u062f\u06cc\u0644 \u06c1\u0648 \u0633\u06a9\u062a\u06cc \u06c1\u06d2\u06d4 \u0639\u0631\u0628\u06cc \u06a9\u06d2 \u0627\u06a9\u062b\u0631 \u0627\u0633\u0645\u0627\u0621 \u0627\u0648\u0631 \u0641\u0639\u0644 \u0645\u0636\u0627\u0631\u0639 \u0645\u0639\u0631\u0628 \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4",'\u0633\u0648\u0631\u0629 \u064a\u0633\u060c \u0622\u06cc\u062a 1: "\u064a\u0633" (\u062d\u0631\u0648\u0641\u0650 \u0645\u0642\u0637\u0639\u0627\u062a \u0645\u0628\u0646\u06cc \u06c1\u06cc\u06ba)')
